<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detalle de anulación</title><style>body{font-family:system-ui;background:#f4f7fb;color:#183453;margin:0;padding:24px}main{max-width:900px;margin:auto;background:#fff;padding:26px;border-radius:14px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #dce6ef;text-align:left}textarea{width:100%;box-sizing:border-box;min-height:110px;padding:10px}button{background:#a42330;color:white;padding:12px 18px;border:0;border-radius:7px;cursor:pointer}.alert{padding:12px;background:#fff0ed;border-radius:7px}a{color:#145ba1}</style></head><body><main><p><a href="{{ route($ruta.'.anulaciones.index') }}">← Volver</a></p><h1>Arqueo {{ $registro->numero_arqueo }}</h1>@if(session('success'))<p>{{ session('success') }}</p>@endif@if($errors->any())<div class="alert">{{ $errors->first() }}</div>@endif<p><strong>Estado:</strong> {{ $registro->estado }} · <strong>Agencia:</strong> {{ $registro->agencia_nombre_historico }} · <strong>Ventanilla:</strong> {{ $registro->ventanilla_codigo_historico }}</p><p><strong>Receptor:</strong> {{ $registro->receptor_nombre_historico }} · <strong>Fecha:</strong> {{ $registro->fecha_operativa?->format('d/m/Y') }}</p><p><strong>Total arqueado:</strong> Q {{ number_format((float)$registro->total_arqueado,2) }} · <strong>Corte:</strong> Q {{ number_format((float)$registro->total_corte,2) }} · <strong>Diferencia:</strong> Q {{ number_format((float)$registro->diferencia,2) }}</p><h2>Desglose original</h2><table><thead><tr><th>Tipo</th><th>Denominación / concepto</th><th>Cantidad</th><th>Subtotal</th></tr></thead><tbody>@foreach($registro->detalles as $detalle)<tr><td>{{ $detalle->tipo }}</td><td>{{ $detalle->denominacion ?? $detalle->concepto }}</td><td>{{ $detalle->cantidad }}</td><td>Q {{ number_format((float)$detalle->subtotal,2) }}</td></tr>@endforeach</tbody></table><h2>Firmas</h2>@foreach($registro->firmas as $firma)<p>{{ $firma->tipo_firma }} — {{ ($verificaciones[$firma->tipo_firma] ?? false) ? 'Integridad verificada' : 'Integridad NO verificada' }} — {{ $firma->fecha_firma?->format('d/m/Y H:i:s') }}</p>@endforeach@if($registro->anulacion)<div class="alert"><strong>Anulado:</strong> {{ $registro->anulacion->fecha_anulacion }}<p><strong>Motivo:</strong> {{ $registro->anulacion->motivo }}</p></div>@elseif($puedeAnular)<h2>Anular arqueo</h2><p>Esta operación es irreversible y conserva los datos económicos y las firmas originales.</p><form method="POST" action="{{ route($ruta.'.anulaciones.store',$registro->id) }}">@csrf<label for="motivo">Motivo obligatorio (10 a 500 caracteres)</label><textarea id="motivo" name="motivo" minlength="10" maxlength="500" required>{{ old('motivo') }}</textarea><p><label><input type="checkbox" name="confirmar_anulacion" value="1" required> Confirmo la anulación irreversible del arqueo.</label></p><button type="submit">Firmar y anular arqueo</button></form>@else<p class="alert">No tiene permiso para anular este arqueo en su estado actual.</p>@endif</main></body></html>